const G=Game,$=s=>document.querySelector(s),money=n=>(n<0?'-':'')+'$'+Math.abs(Math.round(n)).toLocaleString('zh-TW');let saved;try{saved=JSON.parse(localStorage.getItem('meat-day-v1'))}catch{}let state=saved?.state||G.initial(),plan=saved?.plan||G.draft(),result=saved?.result||null,baseline=saved?.baseline||null,replay=saved?.replay||false,view='overview',started=saved?.started||false,filter='all',sceneOnly=!!saved?.started,pendingOutcome=saved?.pendingOutcome||null,playStep=saved?.playStep??0,orderReady=saved?.orderReady||false;plan.staff=G.staffing(plan);
// Reprice saved results consistently while preserving inventory and game progress.
[state.history||[],[result,baseline,pendingOutcome]].flat().forEach(G.repriceResult);

function persist(){try{localStorage.setItem('meat-day-v1',JSON.stringify({state,plan,result,baseline,replay,started,pendingOutcome,playStep,orderReady}))}catch{}}
const navs=[['overview','今日任務','01'],['orders','叫貨管理','02'],['production','加工排程','03'],['inventory','庫存與效期','04'],['finance','營業結算','05']];
function render(){persist();let sc=G.scenario(state.day),r=G.resources(state,plan);$('#app').innerHTML=`<canvas id="shopScene" aria-label="可走動的精肉部門場景"></canvas><div class="game-hud"><a class="brand" href="#" data-action="home"><span class="seal">肉</span><span>肉舖日常<small>主任的一天</small></span></a><span class="hud-status">${pendingOutcome?playbackEvents()[playStep].time:result?'22:00 收工': '09:00 開店準備'} · DAY ${state.day}/14 ${replay?'・重演':''}</span><button class="secondary" data-view="overview">任務</button><button class="secondary" data-view="inventory">庫存</button><button class="secondary" data-view="deputy">副主任</button></div><div class="scene-task"><small>今天你是精肉部門主任</small><b>${pendingOutcome?'營業進行中，聽聽現場的回報。':result?'今天的班結束了，找店長看結算。':orderReady?'叫貨已安排。找阿宏確認排班與加工。':'先找小林了解叫貨，再到加工台排班。'}</b><span>WASD / 方向鍵走動 · 點地板移動 · E 對話</span><button class="primary" data-action="guide">${pendingOutcome?'查看現場回報':'帶我去 →'}</button></div><main class="game-window ${started&&sceneOnly?'hidden':''} ${!started?'welcome':''}"><header><span>${!started?'09:00　20 包雞肉今天到期　主任 ▸ 你':navs.find(x=>x[0]===view)[1]}</span><span class="day">DAY ${String(state.day).padStart(2,'0')} <em>/ 14</em></span>${started?'<button class="quiet" data-action="close">✕ 回肉舖</button>':''}</header>${started?`<nav class="window-nav">${navs.map(([id,n])=>`<button data-view="${id}" class="${id===view?'active':''}">${n}</button>`).join('')}</nav>`:''}<div class="content">${!started?intro():pages[view](sc,r)}</div><footer>教學模擬・價格、需求與效期皆為示範設定。此瀏覽器自動存檔。<button class="quiet" data-action="reset">重新開始</button></footer></main><div id="conversation" class="conversation hidden"></div>`;bind();if(window.initShop)window.initShop();}
function intro(){return `<section class="intro"><div class="eyebrow">09:00 / 主任，今天靠你了。</div><h1>叫得剛好，<br>才是本事。</h1><p class="lead">雞肉今天到期，下午才有新貨。<br>你的每個決定，都會變成晚上的損益。</p><div class="intro-cards"><div><b>20 包</b><span>雞肉今日到期</span></div><div><b>14:00</b><span>外購成品到貨</span></div><div><b>4 班別</b><span>分班加工與休息</span></div></div><button class="primary" data-action="enter">接下今天的班 →</button><p class="muted">先看情報 → 叫貨與加工 → 營業結算 → 重演學習</p><div class="illustration"><span>精 肉</span><div class="display"><i>雞肉<br>89</i><i>火鍋肉片<br>139</i><i>和牛<br>780</i></div><label>FRESH CUTS · EVERY DAY</label></div></section>`;}
function shiftClock(t){return String(Math.floor(t)).padStart(2,'0')+':'+String(Math.round(t*60)%60).padStart(2,'0')}
function heading(k,title,sub){return `<div class="eyebrow">${k}</div><h1>${title}</h1><p class="lead">${sub}</p>`}
function stats(r){return `<div class="stats"><div><small>叫貨預算剩餘</small><b>${money(30000-r.cost)}</b><span>上限 $30,000</span></div><div><small>已排加工</small><b>${r.minutes}<em> / ${r.capacity} 分</em></b><span>依加工順序完成後上架</span></div><div><small>冷藏容量檢查</small><b>${r.kg.toFixed(1)}<em> / 100 kg</em></b><span>以所有到貨合計保守檢查</span></div></div>`}
const pages={overview:(sc,r)=>heading('TODAY’S BRIEF',result?'今天的班，結束了。':'主任，先看今天的情報。',`第 ${state.day} 天 · ${sc.label} · ${sc.weather} · 營業 11:00–22:00`)+stats(r)+`<div class="two"><section class="panel"><span class="tag">今日重點</span><h2>${state.day===1?'上午有需求，下午才到貨。':'把庫存、到貨與加工接起來。'}</h2><p>自製雞肉與外購雞肉，滿足的是同一群客人的需求。叫貨之前，先確認你何時能把商品放上架。</p><div class="notice">${state.batches.filter(b=>b.exp===state.day).map(b=>`${G.products.find(p=>p.id===b.id).name} ${b.qty}${b.type==='raw'?'公斤':'包'}今日到期`).join('；')||'今日沒有到期批次'}。到期未用完會在閉店報廢。</div><button class="primary" data-view="${result?'finance':'orders'}">${result?'查看今日結算':'開始安排叫貨'} →</button></section><section class="panel"><h3>今天怎麼走</h3><ol class="steps"><li><b>09:00 決定叫貨</b><span>看需求區間與批次庫存</span></li><li><b>10:00 原料、加工肉品到貨</b><span>原料依排班加工，完成才可售</span></li><li><b>14:00 包裝成品到貨</b><span>補上下午供應</span></li><li><b>22:00 關店結算</b><span>看缺貨、報廢與可控利益</span></li></ol></section></div><section class="panel"><h3>需求情報 <small>預估不是保證</small></h3><div class="forecast">${G.products.map((p,i)=>`<div><span>${p.name}</span><b>${Math.floor(sc.forecast[i]*.85)}–${Math.ceil(sc.forecast[i]*1.15)} 包</b><small>目前可售 ${G.sum(state.batches,p.id,'finished')} 包</small></div>`).join('')}</div></section>`,
orders:(sc,r)=>heading('ORDER DESK','今天，要叫多少？','09:00 收單 · 每家廠商每日配送一次 · 整數公斤／整數包的示範箱規')+stats(r)+`<section class="panel"><div class="section-head"><h3>採購草稿</h3><button class="quiet" data-action="defaults" ${result||pendingOutcome?'disabled':''}>恢復示範草稿</button></div><div class="table-wrap"><table><thead><tr><th>商品 / 到貨</th><th>現有庫存</th><th>進價</th><th>叫貨量</th><th>小計</th></tr></thead><tbody>${G.products.flatMap(p=>{let a=[{key:p.id,name:p.name+(p.raw?'原料':' '+p.pack),cost:p.raw||p.buy,unit:p.raw?'kg':'包',time:p.raw||p.id==='japan'?'10:00':'14:00',qty:G.sum(state.batches,p.id,p.raw?'raw':'finished')}];if(p.id==='chicken')a.push({key:'chickenPack',name:'包裝雞肉 300g',cost:54,unit:'包',time:'14:00',qty:G.sum(state.batches,'chicken','finished')});return a}).map(p=>`<tr><td><b>${p.name}</b><small>${p.time} 到貨 · ${p.time==='14:00'?'無法補午間缺口':'每日一次配送'}</small></td><td>${p.qty} ${p.unit}</td><td>${money(p.cost)} / ${p.unit}</td><td><input aria-label="${p.name}叫貨量" type="number" min="0" max="1000" step="1" data-order="${p.key}" value="${plan.orders[p.key]}" ${result||pendingOutcome?'disabled':''}> ${p.unit}</td><td>${money(plan.orders[p.key]*p.cost)}</td></tr>`).join('')}</tbody></table></div></section><div class="actionbar"><span>採購合計 <b>${money(r.cost)}</b></span><button class="primary" data-action="order-done">確認草稿・找阿宏 →</button></div>`,
production:(sc,r)=>heading('CUT & PREP','把原料，變成可售商品。','新原料 10:00 到貨 · 各班休息時暫停加工 · 同班多人可平行作業')+stats(r)+`<section class="panel"><h3>今日排班</h3><p class="muted">人事成本 ${money(G.hourlyRate)}／人／小時；早、中、晚班各工作 8 小時；短班工作 5.5 小時。休息不計薪。今日排班共 ${G.laborHours(plan)} 人時，合計 ${money(r.labor)}。加工跨過休息時段會暫停，復工後繼續。</p><div class="shift-grid">${Object.entries(G.shifts).map(([id,shift])=>`<div class="shift-card"><h3>${shift.name}</h3><b>${shiftClock(shift.windows[0][0])}–${shiftClock(shift.windows[0][1])}</b><span>休息 ${shiftClock(shift.windows[0][1])}–${shiftClock(shift.windows[1][0])}</span><b>${shiftClock(shift.windows[1][0])}–${shiftClock(shift.windows[1][1])}</b><small>工作 ${shift.windows.reduce((h,[a,b])=>h+b-a,0)} 小時 · ${money(shift.windows.reduce((h,[a,b])=>h+b-a,0)*G.hourlyRate)}／人</small><label>人數 <input aria-label="${shift.name}人數" type="number" min="0" max="5" step="1" data-staff="${id}" value="${plan.staff[id]}" ${result||pendingOutcome?'disabled':''}></label></div>`).join('')}</div></section><section class="panel"><h3>加工順序與投入量</h3><p class="muted">每公斤完成後即可上架；正常耗損已反映在產出包數。用箭頭調整先後。</p>${plan.sequence.map((id,i)=>{let p=G.products.find(p=>p.id===id),n=plan.production[id],qty=G.sum(state.batches,id,'raw')+plan.orders[id];return `<div class="production-row"><div class="rank">${i+1}</div><div><h3>${p.name}</h3><small>可用 ${qty} kg · 1 kg → ${p.yield} 包 × ${p.pack} · ${p.minutes} 分鐘</small></div><div class="prod-input"><input aria-label="${p.name}加工公斤" type="number" min="0" max="${qty}" step="1" data-prod="${id}" value="${n}" ${result||pendingOutcome?'disabled':''}> kg</div><b>${n*p.yield} 包<small>${n*p.minutes} 分鐘</small></b><button class="quiet" aria-label="${p.name}優先加工" data-up="${id}" ${i===0||result||pendingOutcome?'disabled':''}>↑</button></div>`}).join('')}</section>${supply()}${errors()}<div class="actionbar"><span>${replay?'重演使用相同初始庫存與需求':'決定後，將模擬整天營業'}</span><button class="primary" data-action="run" ${result||pendingOutcome||G.validate(state,plan).length?'disabled':''}>${replay?'開始重演':'確認決策・開始營業'} →</button></div>`,
inventory:()=>heading('STOCK ROOM','每一批，都有期限。','近效期批次優先銷售；已到貨原料完成加工後，才能滿足銷售需求。')+`<section class="panel"><div class="tabs">${[['all','全部'],['raw','原料'],['finished','成品'],['today','今日到期']].map(([k,n])=>`<button class="${filter===k?'selected':''}" data-filter="${k}">${n}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>商品</th><th>批次</th><th>數量</th><th>效期</th><th>庫存成本</th></tr></thead><tbody>${(result?result.batches:state.batches).filter(b=>filter==='all'||b.type===filter||filter==='today'&&b.exp===state.day).map((b,i)=>`<tr><td><b>${G.products.find(p=>p.id===b.id).name}</b><small>${b.type==='raw'?'原料':'可售成品'}</small></td><td>LOT ${i+1}</td><td>${b.qty} ${b.type==='raw'?'kg':'包'}</td><td><span class="${b.exp===state.day?'warning':''}">第 ${b.exp} 天閉店到期</span></td><td>${money(b.qty*b.cost)}</td></tr>`).join('')||'<tr><td colspan="5">這個分類沒有庫存。</td></tr>'}</tbody></table></div></section>`,
finance:()=>result?report():heading('CLOSING REPORT','決定之後，才有答案。','先完成叫貨與加工安排，再開始營業。你的結果會從實際模擬紀錄計算。')+`<button class="primary" data-view="production">前往加工與開店 →</button>`};
function supply(){let jobs;try{jobs=G.schedule(state,plan)}catch{return ''}let demand=G.scenario(state.day).forecast,clock=t=>`${String(Math.floor(t)).padStart(2,'0')}:${String(Math.round(t*60)%60).padStart(2,'0')}`;return `<section class="panel"><h3>這份排班，何時能補上貨？</h3><p class="muted">以下為累計供應量，尚未扣除銷售。加工時間已包含各班的休息安排。</p><div class="table-wrap"><table><thead><tr><th>品項</th><th>首批加工完成</th><th>12:00累計供應</th><th>全天供應</th><th>全天需求參考</th></tr></thead><tbody>${G.products.map((p,i)=>{let own=jobs.filter(j=>j.p.id===p.id),base=G.sum(state.batches,p.id,'finished')+(p.id==='japan'?plan.orders.japan:0),total=base+own.length*(p.yield||0)+(p.id==='chicken'?plan.orders.chickenPack:p.id==='hotpot'?plan.orders.hotpot:0),noon=base+own.filter(j=>j.finish<=12).length*(p.yield||0);return `<tr><td>${p.name}</td><td>${own.length?clock(Math.min(...own.map(j=>j.finish))):'—'}</td><td>${noon} 包</td><td>${total} 包</td><td>${Math.floor(demand[i]*.85)}–${Math.ceil(demand[i]*1.15)} 包</td></tr>`}).join('')}</tbody></table></div><div class="notice">外購雞肉與火鍋肉片 14:00 才到；早班13–14、中班15–16、晚班17–18、短班12:00–12:30休息。晚班才加工的商品無法供應午間需求。</div></section>`}
function errors(){let e=G.validate(state,plan);return e.length?`<div class="notice error">${e.join('；')}</div>`:''}
function report(){let r=result;return heading('CLOSING REPORT',replay?'再做一次，結果改變了嗎？':'22:00，今天收工了。','同一份叫貨決策，最後留下了什麼？')+`<div class="stats"><div><small>部門可控利益</small><b class="${r.profit<0?'warning':''}">${money(r.profit)}</b><span>扣除已售成本、報廢與費用</span></div><div><small>未滿足需求</small><b>${r.missed}<em> 包</em></b><span>各時段缺貨合計，不遞延需求</span></div><div><small>報廢損失</small><b>${money(r.waste)}</b><span>閉店到期原料與成品</span></div></div>${replay&&baseline?`<section class="panel compare"><h3>與正式成績比較</h3><p>利益 ${money(r.profit-baseline.profit)}　／　缺貨 ${r.missed-baseline.missed>0?'+':''}${r.missed-baseline.missed} 包　／　報廢 ${money(r.waste-baseline.waste)}</p><small>初始庫存、需求與價格相同。重演不改寫正式成績。</small></section>`:''}<div class="two"><section class="panel"><h3>今天的損益</h3>${[['淨銷售額',r.revenue],['已售商品成本',-r.cogs],['商品毛利',r.revenue-r.cogs],['報廢損失',-r.waste],['人事成本（'+money(G.hourlyRate)+'／人／小時）',-r.labor],['其他可控費用',-1000],['部門可控利益',r.profit]].map(([n,v])=>`<div class="ledger"><span>${n}</span><b>${money(v)}</b></div>`).join('')}<p class="muted">採購支出 ${money(r.purchase)}；期末庫存 ${money(r.inventoryValue)}。未售庫存保留成本，不全額當日扣除。</p></section><section class="panel"><span class="tag">決策回饋</span><h3>結果從哪裡來？</h3>${r.logs.map(l=>`<div class="feedback"><b>${l.time===12?'午間':l.time===16?'下午':'晚間'} ${l.time}:00</b><p>${l.entries.filter(e=>e.lost).map(e=>`${e.name}需求 ${e.demand} 包，只供應 ${e.sold} 包`).join('；')||'各品項需求都獲得滿足。'}${l.time===12&&l.entries.some(e=>e.lost)?'。14:00 到貨與後續加工，無法回補這段需求。':''}</p></div>`).join('')}<p class="muted">${r.waste?'到期庫存留下了報廢成本。重演時可減少叫貨，或把近效期原料提早加工。':'今日沒有到期報廢；仍需留意保留庫存的後續效期。'}</p></section></div><section class="panel"><h3>商品表現</h3><div class="table-wrap"><table><thead><tr><th>商品</th><th>售出</th><th>缺貨</th><th>剩餘成品</th><th>報廢成本</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.name}</td><td>${x.sold} 包</td><td>${x.lost} 包</td><td>${x.remaining} 包</td><td>${money(x.waste)}</td></tr>`).join('')}</tbody></table></div></section><div class="actionbar"><button class="secondary" data-action="replay">修改決策・重演今天</button><button class="primary" data-action="next">${state.day===14?'查看14天總成績':replay?'回正式成績・進入明天':'保存成績・進入明天'} →</button></div>`;}
function bind(){
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;started=true;sceneOnly=false;render();window.scrollTo(0,0)});
 document.querySelectorAll('[data-order],[data-prod],[data-staff]').forEach(el=>{
  const update=()=>{let n=el.value===''?0:Number(el.value);plan[el.dataset.staff?'staff':el.dataset.order?'orders':'production'][el.dataset.staff||el.dataset.order||el.dataset.prod]=n;persist()};
  el.oninput=update;
  el.onchange=()=>{let scroll=$('.game-window').scrollTop;update();render();$('.game-window').scrollTop=scroll};
 });
 document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{let scroll=$('.game-window').scrollTop,i=plan.sequence.indexOf(b.dataset.up);[plan.sequence[i-1],plan.sequence[i]]=[plan.sequence[i],plan.sequence[i-1]];render();$('.game-window').scrollTop=scroll});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
}
function action(a){if(a==='enter'){started=true;sceneOnly=true;view='overview'}if(a==='order-done'){let e=G.validate(state,{...plan,production:{chicken:0,beef:0,wagyu:0,omi:0}});if(e.length){alert(e.join('；'));return}orderReady=true;sceneOnly=true;render();window.shopGuide?.();return}if(a==='close'){sceneOnly=true}if(a==='home'){started=false}if(a==='guide'){sceneOnly=true;render();if(pendingOutcome)showPlayback();else window.shopGuide?.();return}if(a==='defaults')plan=G.draft();if(a==='play-next'){if(playStep<playbackEvents().length-1){playStep++;render();showPlayback();return}result=pendingOutcome;pendingOutcome=null;if(!replay)baseline=JSON.parse(JSON.stringify(result));view='finance';sceneOnly=false}if(a==='run'){let e=G.validate(state,plan);if(e.length){alert(e.join('；'));return}pendingOutcome=G.simulate(state,plan);playStep=0;sceneOnly=true;render();showPlayback();return}if(a==='replay'){replay=true;result=null;pendingOutcome=null;orderReady=false;view='orders';sceneOnly=false}if(a==='next'){let official=baseline||result;if(state.day===14){let all=[...state.history,official];$('#app main .content').innerHTML=heading('14 DAYS COMPLETE','14 天，你走過來了。','正式成績已保留，重演成績不計入挑戰。')+`<div class="stats"><div><small>累積可控利益</small><b>${money(all.reduce((a,r)=>a+r.profit,0))}</b></div><div><small>累積缺貨</small><b>${all.reduce((a,r)=>a+r.missed,0)} 包</b></div><div><small>累積報廢</small><b>${money(all.reduce((a,r)=>a+r.waste,0))}</b></div></div><section class="panel"><h3>每日成績</h3>${all.map(r=>`<div class="ledger"><span>第 ${r.day} 天 · 缺貨 ${r.missed} 包</span><b>${money(r.profit)}</b></div>`).join('')}</section><button class="primary" data-action="reset">再挑戰一次</button>`;bind();return}state={day:state.day+1,batches:JSON.parse(JSON.stringify(official.batches)),history:[...state.history,official]};plan=G.draft();G.products.filter(p=>p.raw).forEach(p=>plan.production[p.id]=Math.min(plan.production[p.id],G.sum(state.batches,p.id,'raw')+plan.orders[p.id]));result=null;baseline=null;pendingOutcome=null;orderReady=false;replay=false;view='overview';sceneOnly=true}if(a==='reset'){if(!confirm('重新開始14天挑戰？此瀏覽器的目前進度會被重設。'))return;state=G.initial();plan=G.draft();result=baseline=pendingOutcome=null;orderReady=false;replay=false;started=false;view='overview'}render();window.scrollTo(0,0)}

function playbackEvents(){let r=pendingOutcome;if(!r)return [];function recap(index){let log=r.logs[index],lost=log.entries.filter(e=>e.lost);return lost.length?lost.map(e=>`${e.name}缺 ${e.lost} 包`).join('、')+'。這些客人沒有買到，後面到貨也無法補回這次需求。':'這個時段，每個品項的需求都有滿足。';}return [
{time:'11:00 開門營業',who:'小林｜賣場',text:'門打開了，客人開始進來。叫貨單和加工安排已確定。接下來，看不同時段的供應是否接得上。'},
{time:'12:00 午間回報',who:'副主任｜巡場',text:recap(0)},
{time:'14:00 成品到貨',who:'阿宏｜加工',text:`包裝雞肉 ${plan.orders.chickenPack} 包、火鍋肉片 ${plan.orders.hotpot} 包到貨。早班也結束休息，回到工作台。中班15:00、晚班17:00各自開始休息。`},
{time:'16:00 下午回報',who:'副主任｜巡場',text:recap(1)},
{time:'21:00 晚間回報',who:'副主任｜巡場',text:recap(2)},
{time:'22:00 閉店',who:'店長',text:`今天的報廢成本 ${money(r.waste)}，未滿足需求 ${r.missed} 包。來看看損益，再想想明天要怎麼調整。`}
]}
function showPlayback(){let ev=playbackEvents()[playStep];if(!ev)return;const c=$('#conversation');c.classList.remove('hidden');c.innerHTML=`<div class="speaker">${ev.time} · ${ev.who}</div><p>${ev.text}</p><div><button class="primary" data-action="play-next">${playStep===playbackEvents().length-1?'查看今天的結算':'繼續營業'} →</button><button class="quiet" id="look-around">先看看現場</button></div>`;c.querySelector('[data-action]').onclick=()=>action('play-next');$('#look-around').onclick=()=>c.classList.add('hidden');}
